-- Tronic STS portal schema for Supabase (PostgreSQL). Generated by apps/api/scripts/supabase-schema.ts
-- from apps/api/migrations; do not edit by hand. Run once, on an empty project, in the SQL Editor.
BEGIN;
CREATE TABLE IF NOT EXISTS schema_migrations (version text PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT now());

-- 001_init.sql
CREATE TABLE users (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  username text NOT NULL UNIQUE,
  display_name text NOT NULL,
  password_hash text NOT NULL,
  role text NOT NULL CHECK (role IN ('cashier', 'supervisor', 'admin', 'auditor')),
  active boolean NOT NULL DEFAULT true,
  created_at timestamptz NOT NULL DEFAULT now(),
  last_login_at timestamptz
);

-- id is the SHA-256 of the cookie value; the raw session id is never stored.
CREATE TABLE sessions (
  id text PRIMARY KEY,
  user_id uuid NOT NULL REFERENCES users(id),
  csrf_token text NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  expires_at timestamptz NOT NULL
);
CREATE INDEX sessions_user_idx ON sessions(user_id);

CREATE TABLE tariffs (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  code text NOT NULL UNIQUE,
  name text NOT NULL,
  currency text NOT NULL CHECK (currency IN ('KES', 'TZS', 'UGX', 'RWF')),
  created_at timestamptz NOT NULL DEFAULT now()
);

-- Maker-checker: a version becomes active only when a different admin approves it.
CREATE TABLE tariff_versions (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  tariff_id uuid NOT NULL REFERENCES tariffs(id),
  base_rate numeric(18, 4) NOT NULL CHECK (base_rate > 0),
  percent_charges jsonb NOT NULL DEFAULT '[]',
  fixed_charges jsonb NOT NULL DEFAULT '[]',
  status text NOT NULL CHECK (status IN ('draft', 'active', 'retired')),
  note text,
  created_by uuid REFERENCES users(id),
  created_at timestamptz NOT NULL DEFAULT now(),
  approved_by uuid REFERENCES users(id),
  approved_at timestamptz
);
CREATE UNIQUE INDEX tariff_one_active_idx ON tariff_versions(tariff_id) WHERE status = 'active';

CREATE TABLE quotes (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id uuid NOT NULL REFERENCES users(id),
  meter_no text NOT NULL,
  mode text NOT NULL CHECK (mode IN ('units', 'amount')),
  units numeric(18, 2) NOT NULL,
  amount numeric(18, 3) NOT NULL,
  currency text NOT NULL,
  tariff_version_id uuid NOT NULL REFERENCES tariff_versions(id),
  lines jsonb NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  expires_at timestamptz NOT NULL,
  consumed_at timestamptz
);

CREATE TABLE vends (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  client_ref uuid NOT NULL UNIQUE DEFAULT gen_random_uuid(),
  idempotency_key text NOT NULL UNIQUE,
  quote_id uuid NOT NULL UNIQUE REFERENCES quotes(id),
  user_id uuid NOT NULL REFERENCES users(id),
  meter_no text NOT NULL,
  mode text NOT NULL,
  units numeric(18, 2) NOT NULL,
  amount numeric(18, 3) NOT NULL,
  currency text NOT NULL,
  lines jsonb NOT NULL,
  tariff_version_id uuid NOT NULL REFERENCES tariff_versions(id),
  status text NOT NULL CHECK (status IN ('PENDING', 'SUBMITTED', 'SUCCEEDED', 'FAILED', 'UNKNOWN', 'MANUAL_REVIEW')),
  adapter_mode text NOT NULL CHECK (adapter_mode IN ('mock', 'live')),
  vendor_ref text,
  vendor_code text,
  token_enc text,
  token_last4 text,
  error_message text,
  duplicate_confirmed_by uuid REFERENCES users(id),
  resolved_by uuid REFERENCES users(id),
  resolution_note text,
  created_at timestamptz NOT NULL DEFAULT now(),
  submitted_at timestamptz,
  completed_at timestamptz
);
-- At most one unresolved vend per meter.
CREATE UNIQUE INDEX vends_one_open_per_meter_idx ON vends(meter_no)
  WHERE status IN ('PENDING', 'SUBMITTED', 'UNKNOWN', 'MANUAL_REVIEW');
CREATE INDEX vends_meter_created_idx ON vends(meter_no, created_at DESC);
CREATE INDEX vends_created_idx ON vends(created_at DESC);

CREATE TABLE vend_attempts (
  id bigserial PRIMARY KEY,
  vend_id uuid NOT NULL REFERENCES vends(id),
  operation text NOT NULL,
  outcome text NOT NULL,
  latency_ms integer,
  detail jsonb,
  at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE receipt_prints (
  id bigserial PRIMARY KEY,
  vend_id uuid NOT NULL REFERENCES vends(id),
  user_id uuid NOT NULL REFERENCES users(id),
  reprint boolean NOT NULL,
  at timestamptz NOT NULL DEFAULT now()
);

-- Append-only, hash-chained. In production, grant the app role INSERT and SELECT only.
CREATE TABLE audit_events (
  id bigserial PRIMARY KEY,
  at timestamptz NOT NULL,
  actor_id uuid REFERENCES users(id),
  action text NOT NULL,
  entity text,
  entity_id text,
  detail jsonb,
  payload text NOT NULL,
  prev_hash text NOT NULL,
  hash text NOT NULL
);
CREATE INDEX audit_events_at_idx ON audit_events(at DESC);

-- Live STS mode needs approval from two different admins (plus the environment flag).
CREATE TABLE live_mode_approvals (
  admin_id uuid PRIMARY KEY REFERENCES users(id),
  approved_at timestamptz NOT NULL DEFAULT now()
);
INSERT INTO schema_migrations(version) VALUES ('001_init.sql');

-- 002_customers.sql
-- Registered customers buy tokens for their own meter from a prepaid balance.
-- Staff top the balance up at the counter after taking payment; there is no payment gateway.
CREATE TABLE customers (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  meter_no text NOT NULL UNIQUE,
  name text NOT NULL,
  phone text,
  pin_hash text NOT NULL,
  balance numeric(18, 3) NOT NULL DEFAULT 0 CHECK (balance >= 0),
  currency text NOT NULL,
  active boolean NOT NULL DEFAULT true,
  created_by uuid REFERENCES users(id),
  created_at timestamptz NOT NULL DEFAULT now(),
  last_login_at timestamptz
);

-- id is the SHA-256 of the cookie value, as for staff sessions.
CREATE TABLE customer_sessions (
  id text PRIMARY KEY,
  customer_id uuid NOT NULL REFERENCES customers(id),
  csrf_token text NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  expires_at timestamptz NOT NULL
);
CREATE INDEX customer_sessions_customer_idx ON customer_sessions(customer_id);

-- Every balance change. amount is signed: top-ups and refunds add, purchases subtract.
CREATE TABLE customer_ledger (
  id bigserial PRIMARY KEY,
  customer_id uuid NOT NULL REFERENCES customers(id),
  kind text NOT NULL CHECK (kind IN ('topup', 'purchase', 'refund')),
  amount numeric(18, 3) NOT NULL,
  balance_after numeric(18, 3) NOT NULL,
  vend_id uuid REFERENCES vends(id),
  user_id uuid REFERENCES users(id),
  idempotency_key text UNIQUE,
  note text,
  created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX customer_ledger_customer_idx ON customer_ledger(customer_id, created_at DESC);

ALTER TABLE vends ADD COLUMN customer_id uuid REFERENCES customers(id);
CREATE INDEX vends_customer_idx ON vends(customer_id, created_at DESC) WHERE customer_id IS NOT NULL;

-- Customer purchases run through the same quote and vend pipeline under this account.
-- It is inactive with an unusable password hash, so nobody can sign in as it.
INSERT INTO users (username, display_name, password_hash, role, active)
VALUES ('self-service', 'Customer self-service', '!', 'cashier', false);
INSERT INTO schema_migrations(version) VALUES ('002_customers.sql');

-- 003_customer_no_balance.sql
-- Customers no longer pay from a portal balance: the tenant settles payment outside the portal.
-- Each customer's tokens stay on record through vends.customer_id.
DROP TABLE customer_ledger;
ALTER TABLE customers DROP COLUMN balance;
INSERT INTO schema_migrations(version) VALUES ('003_customer_no_balance.sql');

-- 004_tenant_wording.sql
-- Registered customers are tenants of a landlord; the self-service account shows up as the operator on their tokens.
UPDATE users SET display_name = 'Tenant self-service' WHERE username = 'self-service';
INSERT INTO schema_migrations(version) VALUES ('004_tenant_wording.sql');

-- 005_landlords.sql
-- Landlords sign in like staff but see and manage only their own tenants.
ALTER TABLE users DROP CONSTRAINT users_role_check;
ALTER TABLE users ADD CONSTRAINT users_role_check CHECK (role IN ('cashier', 'supervisor', 'admin', 'auditor', 'landlord'));

-- Which landlord a tenant belongs to. NULL for tenants Tronic manages directly.
ALTER TABLE customers ADD COLUMN landlord_id uuid REFERENCES users(id);
CREATE INDEX customers_landlord_idx ON customers(landlord_id);
INSERT INTO schema_migrations(version) VALUES ('005_landlords.sql');

-- 006_supabase_lockdown.sql
-- Supabase serves every table in the public schema through its Data API to anyone holding the project's
-- anon key. The portal reaches the database only through its own API server, so the Data API roles get no
-- access, and row level security with no policies blocks them as a backstop. The portal connects as the
-- table owner, which row level security does not restrict. New tables in later migrations need the same.
DO $$
DECLARE t text;
BEGIN
  FOR t IN SELECT tablename FROM pg_tables WHERE schemaname = 'public' LOOP
    EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY', t);
  END LOOP;
  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'anon') THEN
    REVOKE ALL ON ALL TABLES IN SCHEMA public FROM anon, authenticated;
    REVOKE ALL ON ALL SEQUENCES IN SCHEMA public FROM anon, authenticated;
    ALTER DEFAULT PRIVILEGES IN SCHEMA public REVOKE ALL ON TABLES FROM anon, authenticated;
    ALTER DEFAULT PRIVILEGES IN SCHEMA public REVOKE ALL ON SEQUENCES FROM anon, authenticated;
  END IF;
END $$;
INSERT INTO schema_migrations(version) VALUES ('006_supabase_lockdown.sql');

COMMIT;
